from dataclasses import dataclass

@dataclass(frozen=True)
class Enrollment:
    repository: str
    enabled: bool

class EnrollmentStore:
    def __init__(self):
        self.records = {}

    def register(self, repository):
        if repository not in self.records:
            self.records[repository] = Enrollment(repository, enabled=True)
        return self.records[repository]

    def status(self, repository):
        return self.records[repository]

